// 启程条款与半日航损各在原执行成功处登记；不产生第二份旅行、钱货或时钟。
#include "naval_navigation_integration.hpp"
#include "naval_integration.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {
Outcome<std::optional<NavalVoyageFact>> prepare_naval_voyage_world(const WorldBundle& w,const StableId& actor,const TravelQuote& quote){if(!w.naval_navigation_enabled()||quote.road||quote.mode!="boat")return {true,std::nullopt,{}};auto access=w.services.military_access();auto result=preview_naval_voyage(w.common,w.military,*w.catalog->military,access,w.naval,*w.catalog->naval,*w.catalog->naval->navigation_policy,actor,quote);if(!result.ok)return {false,{},result.error};return {true,std::move(result.value),{}};}
Status record_naval_voyage_world(WorldBundle& w,const std::optional<NavalVoyageFact>& prepared,const StableId& action){if(!prepared)return common_success();if(!w.naval_navigation_enabled())return common_failure("NavalNavigationProfileRequired");const auto* params=w.travel.actions.find(action);if(!params)return common_failure("NavalVoyageActionRequired",action);auto recorded=record_naval_voyage(w.common,w.travel,w.naval.navigation,*prepared,params->plan_id);return {recorded.ok,{},recorded.error};}
Outcome<NavalNavigationStepFact> step_naval_navigation_world(WorldBundle& w,const TerrainExecution& executed,const DynamicStepInput& phase){if(!w.naval_navigation_enabled())return {false,{},common_failure("NavalNavigationProfileRequired").error};auto access=w.services.military_access(phase.to_tick,&phase);auto geometry=naval_history_access(w);return apply_naval_navigation_step(w.common,w.military,*w.catalog->military,access,w.travel,w.naval,*w.catalog->naval,*w.catalog->naval->navigation_policy,w.naval.navigation,geometry,{executed,std::nullopt,{}},phase);}
// 接敌必须先冻原已磨损战场，再退出途中失能的原Action；完成回执在clock_commit后读精确新来源。
Status release_disabled_naval_journeys(WorldBundle& w,const DynamicStepInput& phase){if(!w.naval_navigation_enabled())return common_success();if(phase.from_tick!=w.common.tick()||phase.to_tick!=phase.from_tick+1)return common_failure("NavalNavigationPhaseRequired");for(const auto& step:w.naval.navigation.steps)if(step.tick==phase.to_tick&&step.interrupted){const auto* action=w.common.action(step.movement.action_id);if(!action||action->kind!="travel"||action->actor_id!=step.movement.actor_id||action->start_tick!=step.movement.action_start_tick)return common_failure("NavalNavigationTerminationActionMismatch",step.id);auto result=release_action(w,action->id);if(!result.ok)return result;}return common_success();}
}
